mapper.sql:
WHERE cs.counselor_id = #{query.counselorId}

    AND (su.real_name LIKE CONCAT('%', #{query.studentKeyword}, '%')
         OR sp.student_no LIKE CONCAT('%', #{query.studentKeyword}, '%')
         OR sp.college LIKE CONCAT('%', #{query.studentKeyword}, '%')
         OR pt.type_name LIKE CONCAT('%', #{query.studentKeyword}, '%'))


    AND cs.consultation_date >= #{query.startDate}


    AND cs.consultation_date <= #{query.endDate}


    AND cs.schedule_status = #{query.status}

