UPDATE consultation_schedule
SET schedule_status = 'CLOSED',
    update_time = NOW()
WHERE student_id = #{studentId}
  AND counselor_id = #{counselorId}
  AND schedule_status IN ('RESERVED', 'COMPLETED', 'ABSENT', 'LEAVE', 'DROPPED')
